DROP TRIGGER to_sheet_source_evidence ON public.visit_personnel;
COMMENT ON FUNCTION public.guard_sheet_source_edit() IS 'DEPRECATED: TO sheet snapshots retain originals; existing punch approval and correction paths must remain unchanged';
CREATE FUNCTION public.record_to_sheet_signature(p_sheet uuid,p_person uuid,p_role text,p_in timestamptz,p_out timestamptz,p_path text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s record;cap int;cnt int;rid uuid;BEGIN IF auth.uid() IS NULL OR NOT(has_role(auth.uid(),'admin') OR has_role(auth.uid(),'manager')) THEN RAISE EXCEPTION 'Manager access required';END IF;SELECT sh.*,t.location_id,t.effective_date,t.kind to_kind,l.project_id,COALESCE(l.timezone,'America/Chicago') tz INTO s FROM location_to_sheets sh JOIN location_task_orders t ON t.id=sh.task_order_id JOIN project_locations l ON l.id=t.location_id WHERE sh.id=p_sheet AND t.status='accepted';IF NOT FOUND THEN RAISE EXCEPTION 'Accepted sheet required';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(p_sheet::text,2));IF p_in IS NULL OR p_out IS NULL OR p_out<=p_in OR p_out>p_in+interval '24 hours' OR (p_in AT TIME ZONE s.tz)::date<>s.effective_date THEN RAISE EXCEPTION 'Enter times on the TO effective date, no more than 24 hours';END IF;
IF NOT EXISTS(SELECT 1 FROM location_assignments WHERE location_id=s.location_id AND personnel_id=p_person AND assigned_at<=p_out AND (unassigned_at IS NULL OR unassigned_at>=p_in)) THEN RAISE EXCEPTION 'Person must be assigned to this location on the sheet date';END IF;IF EXISTS(SELECT 1 FROM signin_sheet_days WHERE location_id=s.location_id AND sheet_date=(p_in AT TIME ZONE s.tz)::date AND status='locked') OR EXISTS(SELECT 1 FROM time_week_closeouts WHERE project_id=s.project_id AND status='closed' AND week_start_date<=(p_in AT TIME ZONE 'America/Chicago')::date AND week_end_date>=(p_in AT TIME ZONE 'America/Chicago')::date) THEN RAISE EXCEPTION 'Reopen the locked day or payroll week before adding evidence';END IF;
IF p_path NOT LIKE s.project_id::text||'/to-sheets/'||p_sheet::text||'/%' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='project-documents' AND name=p_path) THEN RAISE EXCEPTION 'Private immutable sheet signature required';END IF;
SELECT COALESCE(sum((x->>'count')::int),0) INTO cap FROM jsonb_array_elements(s.required_counts) x WHERE lower(x->>'label')=lower(p_role);SELECT count(*) INTO cnt FROM location_to_sheet_entries WHERE sheet_id=p_sheet AND lower(role_label)=lower(p_role) AND voided_at IS NULL;IF cnt>=cap THEN RAISE EXCEPTION 'Sheet role count fulfilled';END IF;
INSERT INTO location_to_sheet_entries(sheet_id,personnel_id,role_label,in_at,out_at,signature_url,signed_at,created_by) VALUES(p_sheet,p_person,p_role,p_in,p_out,p_path,now(),auth.uid()) RETURNING id INTO rid;INSERT INTO audit_logs(user_id,user_email,action_type,resource_type,resource_id,changes_after,metadata) VALUES(auth.uid(),'to-sheet-signature','to_sheet_signature','location_to_sheet_entries',rid,jsonb_build_object('sheet_id',p_sheet,'personnel_id',p_person,'in_at',p_in,'out_at',p_out),jsonb_build_object('billing_only',true,'does_not_modify_punches',true));RETURN rid;END $$;REVOKE ALL ON FUNCTION public.record_to_sheet_signature(uuid,uuid,text,timestamptz,timestamptz,text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.record_to_sheet_signature(uuid,uuid,text,timestamptz,timestamptz,text) TO authenticated;